import {createProject,ORBITS,SOURCES,BASIS_LABELS} from './data.js';
import {evaluate,validateProject,verificationTasks,zeroEventUpperRate,environmentCsv,importEnvironmentCsv,toCsv,CSV_COLUMNS,buildEnvironmentIndex} from './model.js';

import {createLab,validateLab,resetMemory,flipBit,injectPreset,scrubMemory,inspectLab,runCampaign,ARCHITECTURES,PATTERNS} from './fault-lab.js';
import {labPage} from './lab-view.js';

let project=createProject(),page='lab',toastTimer,campaign=null;
const app=document.querySelector('#app');
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>v===null||v===undefined?'자료 부족':v===Infinity?'∞':v!==0&&Math.abs(v)<.001?v.toExponential(2):new Intl.NumberFormat('ko-KR',{maximumFractionDigits:d}).format(v);
const won=v=>v===null?'견적 필요':v>=1e8?`${fmt(v/1e8)}억`:v>=1e4?`${fmt(v/1e4)}만`:fmt(v);
const modeLabel={none:'보호 없음',ecc:'ECC + 스크러빙',tmr:'TMR + 재동기화'};
const icons={chip:'M8 8h8v8H8zM9 3v5m6-5v5M9 16v5m6-5v5M3 9h5m-5 6h5m8-6h5m-5 6h5',chart:'M4 4v16h17M8 15v-4m5 4V7m5 8v-6',layers:'m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',check:'M9 5h11M9 12h11M9 19h11M3 5h1M3 12h1M3 19h1',cost:'M4 5h16v14H4zM4 9h16M8 13h2m4 0h2M8 16h2m4 0h2',data:'M5 3h10l4 4v14H5zM14 3v5h5M8 12h8m-8 4h8',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',info:'M12 8h.01M12 11v5M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',arrow:'M5 12h14m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',print:'M7 8V3h10v5M6 17H3V9h18v8h-3M7 14h10v7H7z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',compare:'M7 3v18M17 3v18M7 8H3m4 8H3M17 8h4m-4 8h4'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.chip}"/></svg>`;
const badge=(text,type='')=>`<span class="badge ${type}">${h(text)}</span>`;
const sourceLink=s=>/^https?:\/\//i.test(s)?`<a href="${h(s)}" target="_blank" rel="noopener noreferrer">원문 자료 ↗</a>`:h(s);
const btn=(text,action,ico='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${h(text)}</button>`;
const selected=()=>project.parts.find(p=>p.id===project.selectedPartId);
const getPath=(path)=>path.split('.').reduce((o,k)=>o[k],project);
function input(path,label,opts={}){const value=opts.value!==undefined?opts.value:getPath(path);return `<label><span>${h(label)}</span><input data-path="${h(path)}" aria-label="${h(label)}" type="${opts.type||'number'}" value="${h(value===null?'':value)}" ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} step="${opts.step||'any'}" ${opts.nullable?'data-nullable="true"':''} ${opts.percent?'data-percent="true"':''}>${opts.help?`<small class="help">${h(opts.help)}</small>`:''}</label>`;}
function partInput(key,label,opts={}){const p=selected();return input(`part.${key}`,label,{...opts,value:opts.value!==undefined?opts.value:p[key]});}
function selectPath(path,label,options){return `<label><span>${h(label)}</span><select data-path="${h(path)}" data-string="true" aria-label="${h(label)}">${options.map(([value,text])=>`<option value="${h(value)}" ${getPath(path)===value?'selected':''}>${h(text)}</option>`).join('')}</select></label>`;}
function partPicker(){return `<select class="part-select" data-path="selectedPartId" data-string="true" aria-label="평가 부품 선택">${project.parts.map(p=>`<option value="${h(p.id)}" ${p.id===project.selectedPartId?'selected':''}>${h(p.name)}</option>`).join('')}</select>`;}
function card(title,body,extra='',sub=''){return `<section class="card"><div class="card-head"><div><h2>${title}</h2>${sub?`<p class="card-sub">${sub}</p>`:''}</div>${extra}</div>${body}</section>`;}
function metric(label,value,unit,foot,cls=''){return `<div class="card metric"><div class="metric-label">${h(label)}</div><div class="metric-value ${cls}">${h(value)}${unit?`<small>${h(unit)}</small>`:''}</div><div class="metric-foot">${h(foot)}</div></div>`;}
function notice(text,type=''){return `<div class="notice ${type}">${icon('info')}<p>${text}</p></div>`;}
function kv(label,value){return `<div class="kv"><span>${h(label)}</span><b>${value}</b></div>`;}
function table(headers,rows,note=''){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${note?`<p class="table-note">${note}</p>`:''}`;}
function controls(){return `<section class="card controls" aria-label="공통 임무 조건">${selectPath('mission.orbitId','목표 궤도',ORBITS.map(o=>[o.id,o.label]))}${input('mission.years','임무 수명 (년)',{min:.01,max:50,step:.5})}${input('mission.shieldMm','Al 등가 차폐 (mm)',{min:.01,max:100,step:.5,help:'일치하는 차폐 자료만 사용'})}${input('mission.doseMargin','선량 설계 여유계수',{min:1,max:20,step:.5})}</section>`;}
function evidenceNotice(r){if(r.synthetic)return notice('<strong>예시 데이터로 분석 중</strong> 환경 수치와 가상 부품은 계산 흐름을 확인하기 위한 합성 자료입니다. 실제 궤도 예측·부품 선정에는 출처가 있는 환경·시험자료를 가져오세요.');return notice('<strong>입력자료 기반 예비 평가</strong> 수치 여유와 자료 공백을 함께 검토하세요. 최종 적용 판단에는 로트·동작조건·파괴성 효과의 근거가 필요합니다.','info');}

const pages={lab:['반도체 설계 실험실','BIT-LEVEL DESIGN LAB','비트를 직접 뒤집고, 오류 정정·검출·복구 동작을 비교합니다.','layers'],overview:['분석 대시보드','MISSION OVERVIEW','목표 궤도에서의 선량·오류·비용을 함께 비교합니다.','chart'],parts:['부품·시험자료','COMPONENT EVIDENCE','제품 사양, 시험자료와 사용자 가정을 구분해 관리합니다.','chip'],compare:['부품 비교','CANDIDATE COMPARISON','같은 임무 조건에서 후보 부품의 TID 여유·오류율·비용·근거 상태를 나란히 비교합니다.','compare'],protection:['보호·복구 설계','FAULT MITIGATION','오류정정·복구 가정을 바꾸고 잔존 사건과 중단시간을 비교합니다.','shield'],verification:['검증계획','VERIFICATION PLAN','부품의 근거를 정리하고 Space-MaCS 이후의 검증 공백을 확인합니다.','check'],cost:['비용·양산 비교','COST COMPARISON','소자·보호설계·차폐·시험·개발비를 동일 물량에서 비교합니다.','cost'],data:['자료·계산방법','DATA & METHODS','분석자료를 가져오고 계산 가정과 출처를 확인합니다.','data']};
function render(){
 // project is always already validated by the time it reaches here: update() validates its
 // draft before assigning it and calling render(); the file-load and CSV-import handlers
 // (below) validate explicitly before assigning; createProject() is a trusted internal
 // factory. Re-validating on every render (including plain page navigation) was pure
 // duplicate work over up to 100 parts / 3,000 environment rows.
 const r=evaluate(project),p=pages[page];
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${icon('chip')}<div><strong>K-LEO <span style="color:#5be3b6">CHIP</span></strong><small>SPACE ELECTRONICS LAB</small></div></div><div class="nav-caption">분석 워크스페이스</div><nav class="nav" aria-label="분석 메뉴">${Object.entries(pages).map(([id,x])=>`<button type="button" data-page="${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${icon(x[3])}${x[0]}</button>`).join('')}</nav><div class="side-bottom"><p>궤도 조건부터<br>반도체 적용·검증까지</p><span class="version">V1.1.0 · DESIGN LAB</span></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">K-LEO / <strong>우주반도체 적용성</strong></div><div class="top-actions">${btn('불러오기','load','upload')}${btn('시나리오 저장','save','download')}${btn('보고서 인쇄','print','print')}</div></header><main class="main" id="main"><div class="page-heading"><div><p class="eyebrow">${p[1]}</p><h1>${p[0]}</h1><p class="subheading">${p[2]}</p></div>${page==='lab'?(campaign?btn('실험 CSV','lab-csv','download'):btn('궤도별 분석','go-overview','arrow')):btn('결과 CSV','results','download')}</div>${page==='lab'?'':controls()+evidenceNotice(r)}${({lab:()=>labPage(project.lab,campaign,{card,btn,badge,table,fmt,h,notice,metric}),overview:overview,parts:partsPage,compare:comparePage,protection:protectionPage,verification:verificationPage,cost:costPage,data:dataPage}[page])(r)}<footer class="footer"><span>K-LEO CHIP · ${h(project.title)}</span><span>메모리 설계·적용성 · <a href="./kleo-chip-v1.1.0-source.zip" download>소스 코드 다운로드</a></span></footer></main></div></div>`;
}
function doseChart(){
 const envIndex=buildEnvironmentIndex(project);
 const rs=ORBITS.map(o=>evaluate(project,project.selectedPartId,o.id,envIndex));const limit=selected().tidKrad===null?null:selected().tidKrad/project.mission.doseMargin;
 const vals=rs.map(r=>r.missionDose).filter(v=>v!==null);if(!vals.length)return '<div class="empty"><strong>환경자료가 필요합니다</strong>목표 궤도·차폐 조건에 맞는 연간 선량을 가져오세요.</div>';
 const max=Math.max(...vals,limit||0,1)*1.15,w=760,ht=245,left=55,right=25,top=20,bottom=38,plotW=w-left-right,plotH=ht-top-bottom;
 const x=t=>left+plotW*t/project.mission.years,y=d=>ht-bottom-d/max*plotH,colors=['#7a60af','#087f76','#4772c6'];
 const grid=Array.from({length:5},(_,i)=>{const v=max*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e7edf1"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}</text>`;}).join('');
 const xs=Array.from({length:6},(_,i)=>{const t=project.mission.years*i/5;return `<text x="${x(t)}" y="${ht-12}" text-anchor="middle">${fmt(t,1)}년</text>`;}).join('');
 const lines=rs.map((r,i)=>r.missionDose===null?'':`<path d="M ${x(0)} ${y(0)} L ${x(project.mission.years)} ${y(r.missionDose)}" stroke="${colors[i]}" stroke-width="${ORBITS[i].id===project.mission.orbitId?3.5:2}" fill="none"/><circle cx="${x(project.mission.years)}" cy="${y(r.missionDose)}" r="4" fill="${colors[i]}"/>`).join('');
 return `<div class="chart-wrap"><svg class="chart" viewBox="0 0 ${w} ${ht}" role="img" aria-label="임무기간에 비례한 궤도별 누적선량 비교. 정확한 값은 아래 비교표에 있습니다."><text x="${left}" y="12" class="axis-title">krad(Si)</text>${grid}${xs}${limit===null?'':`<line x1="${left}" x2="${w-right}" y1="${y(limit)}" y2="${y(limit)}" stroke="#bf8235" stroke-dasharray="6 4"/><text x="${left+12}" y="${Math.max(18,y(limit)-8)}" style="fill:#946428">부품 TID ÷ 여유계수</text>`}${lines}</svg></div><p class="chart-caption">연간 평균 선량을 임무기간에 비례 적용한 비교입니다. 태양활동의 시간 변화는 계산하지 않습니다.</p>`;
}
function doseEvidenceBadge(r){
 if(r.synthetic)return badge('예시','amber');
 if(r.doseInterpolated)return badge('차폐 보간값','blue');
 if(r.doseNearestOnly)return badge('범위 밖 근접값','amber');
 if(r.dose)return badge('입력자료','blue');
 return badge('자료 부족');
}
function orbitRows(){const envIndex=buildEnvironmentIndex(project);return ORBITS.map(o=>{const r=evaluate(project,project.selectedPartId,o.id,envIndex);return `<tr class="${o.id===project.mission.orbitId?'selected':''}"><td><button class="btn quiet" data-orbit="${o.id}" aria-label="${h(o.label)} 선택" style="padding:0;min-height:32px">${h(o.label)}${o.id===project.mission.orbitId?'<span class="selected-tag">선택</span>':''}</button><span class="secondary">${h(o.name)}</span></td><td class="number">${fmt(r.missionDose)}</td><td class="number">${fmt(r.requiredDose)}</td><td class="number">${fmt(r.tidRatio)}${r.tidRatio===null?'':' ×'}</td><td class="number">${fmt(r.soft?.rawPerDay)}</td><td>${doseEvidenceBadge(r)}</td></tr>`;});}
function overview(r){
 const part=r.part;
 return `<div class="metrics">${metric('임무 누적선량',fmt(r.missionDose),r.missionDose===null?'':'krad(Si)',`${project.mission.years}년 · ${project.mission.shieldMm} mm Al 등가`)}${metric('TID 수치 여유',fmt(r.tidRatio),r.tidRatio===null?'':'배','부품 TID / 여유계수 적용 요구량',r.tidRatio!==null&&r.tidRatio<1?'text-red':'')}${metric('원시 비트 오류',fmt(r.soft?.rawPerDay),r.soft?'회/일':'',`논리 장비 1대 · 소자 ${project.mission.devicesPerBoard}개 기준`)}${metric('제작·검증 비용',won(r.cost.total),r.cost.total===null?'':'원',`예비품 포함 장비 ${fmt(r.cost.boards,0)}대 · 가정 비용`)}</div><div class="grid-two">${card('누적선량 비교',doseChart(),`<div class="legend"><span><i class="swatch" style="background:#7a60af"></i>500 km</span><span><i class="swatch"></i>888 km</span><span><i class="swatch" style="background:#4772c6"></i>1,280 km</span></div>`)}${card('평가 중인 반도체',`<div class="card-body"><div class="pill-row">${badge(part.grade)}${badge(BASIS_LABELS[part.tidBasis],part.tidBasis==='synthetic'?'amber':'blue')}</div>${partPicker()}<p class="part-description">${h(part.vendor)} · ${fmt(part.densityBits/1048576)} Mibit</p>${kv('TID 근거',`${fmt(part.tidKrad)} krad(Si)`)}${kv('보호설계',h(modeLabel[project.protection.mode]))}${kv('추가 확인 항목',`${r.reasons.length}개`)}<div class="spaced">${btn('부품 자료 검토','go-parts','arrow')}</div></div>`)}</div><div class="spaced">${card('같은 부품, 세 가지 임무환경',table(['궤도','누적선량<br>krad(Si)','요구선량<br>krad(Si)','TID 여유','원시 오류<br>회/일','환경 근거'],orbitRows(),'TID 여유가 1배 이상이어도 SEE·구매 로트·동작조건을 별도 검증해야 합니다. 오류 횟수는 위성 고장확률이 아닙니다.'))}</div><div class="grid-equal">${card('검증이 필요한 근거',`<div class="card-body"><div class="pill-row">${r.reasons.length?r.reasons.map(x=>badge(x,'amber')).join(''):badge('입력 항목 확보 · 내용 검토 필요','blue')}</div><p class="input-note">${h(part.notes)}</p><div class="spaced">${btn('검증계획 보기','go-verification','arrow')}</div></div>`)}${card('현재 분석조건',`<div class="card-body">${kv('환경 모델',h(r.dose?.model||'자료 부족'))}${kv('시기·태양활동',h(r.dose?.epoch||'자료 부족'))}${kv('환경 출처',sourceLink(r.dose?.source||'자료 부족'))}${kv('부품 출처',sourceLink(part.tidSource))}</div>`)}</div>`;
}
function partsPage(r){
 const envIndex=buildEnvironmentIndex(project);
 const rows=project.parts.map(p=>{const ev=evaluate(project,p.id,project.mission.orbitId,envIndex);return `<tr class="${p.id===project.selectedPartId?'selected':''}"><td><button class="btn quiet" data-part="${h(p.id)}" style="padding:0;text-align:left;white-space:normal">${h(p.name)}</button><span class="secondary">${h(p.vendor)} · ${h(p.id)}</span></td><td>${h(p.grade)}</td><td class="number">${fmt(p.densityBits/1048576)}</td><td class="number">${fmt(p.tidKrad)}</td><td>${badge(BASIS_LABELS[p.tidBasis],p.tidBasis==='synthetic'?'amber':'blue')}</td><td>${ev.soft?badge('입력 있음','blue'):badge('자료 부족')}</td></tr>`;});
 return `${card(`부품 라이브러리 <span class="count">${project.parts.length}</span>`,table(['부품','분류','Mibit','TID<br>krad(Si)','TID 근거','목표궤도 SEU'],rows,'공개 제품 사양 3종과 합성 부품 3종을 포함합니다. 공개 사양은 구매 로트 시험성적서와 구분합니다.'),btn('사용자 부품 추가','add-part','plus'))}<div class="grid-equal">${card(h(r.part.name),`<div class="card-body"><div class="field-grid">${partInput('name','부품명',{type:'text'})}${partInput('vendor','제조사',{type:'text'})}${partInput('densityBits','메모리 비트 수',{min:1,step:1,help:'16 Mibit = 16,777,216 bit'})}${partInput('tidKrad','TID 근거값 (krad(Si))',{nullable:true,min:0,help:'미확보 시 비워두세요'})}${partInput('lot','제조 로트·리비전',{type:'text'})}<label><span>TID 근거 유형</span><select data-part-basis="true">${Object.entries(BASIS_LABELS).map(([v,n])=>`<option value="${v}" ${r.part.tidBasis===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="full">${partInput('tidSource','TID 자료 제목 또는 URL',{type:'text'})}</div><label class="full"><span>시험조건·판정기준·제한사항</span><textarea data-path="part.notes">${h(r.part.notes)}</textarea></label></div><p class="input-note">TID 값·용량·출처를 수정하면 근거 유형이 ‘사용자 자료’로 전환됩니다. 원래 출처와 변경 내용을 함께 기록하세요.</p></div>`,btn('복제','clone-part','plus'))}${card('자료 해석',`<div class="card-body explain"><p><strong>제조사 사양</strong>은 제품군의 공개 성능입니다. 선량률·바이어스·온도·어닐링·실패 기준과 구매 등급을 확인해야 합니다.</p><p><strong>SEU</strong>는 목표궤도와 차폐 조건에 해당하는 부품별 원시 비트 오류율이 있어야 계산합니다. 내장 EDAC 적용 후 오류율은 V1.0 보호모델에 다시 넣지 않습니다.</p><p><strong>SEL 시험 LET</strong> 하나로 SEU 곡선이나 모든 임무의 내성을 추정하지 않습니다. 미관측 시험의 입자 플루언스와 동작조건을 확인하세요.</p><p class="spaced">${sourceLink(r.part.tidSource)}</p><div class="spaced">${btn('환경·오류율 자료 입력','go-data','arrow')}</div></div>`)}</div>`;
}
