function protectionPage(r){
 const p=project.protection;
 // evaluate() doesn't mutate its input, and only protection.mode differs between the three
 // alternatives here, so a shallow override plus one shared environment index (instead of a
 // full structuredClone(project) and a fresh environments scan per alternative) is enough.
 const envIndex=buildEnvironmentIndex(project);
 const alternatives=['none','ecc','tmr'].map(mode=>({mode,r:evaluate({...project,protection:{...project.protection,mode}},project.selectedPartId,project.mission.orbitId,envIndex)}));
 const max=Math.max(...alternatives.map(a=>a.r.soft?.uncorrectablePerDay||0),1e-15);
 const bars=alternatives.map(a=>`<div class="bar-row"><span>${h(modeLabel[a.mode])}</span><div class="bar"><i style="width:${Math.min(100,(a.r.soft?.uncorrectablePerDay||0)/max*100)}%;background:${a.mode===p.mode?'#087f76':'#98b8c6'}"></i></div><b>${fmt(a.r.soft?.uncorrectablePerDay)}</b></div>`).join('');
 return `<div class="grid-equal" style="margin-top:0">${card('보호설계 가정',`<div class="card-body">${partPicker()}<div class="segmented" aria-label="보호설계 선택">${['none','ecc','tmr'].map(mode=>`<button data-mode="${mode}" class="${p.mode===mode?'active':''}" aria-pressed="${p.mode===mode}">${mode==='none'?'보호 없음':mode==='ecc'?'ECC':'TMR'}</button>`).join('')}</div><div class="field-grid spaced">${input('mission.devicesPerBoard','장비당 소자 수',{min:1,step:1})}${input('protection.wordBits','보호 워드 길이 (bit)',{min:8,max:4096,step:1})}${input('protection.scrubSec','점검·복구 주기 (초)',{min:.01,max:86400})}${input('protection.recoverySec','기능 복구시간 (초)',{min:0,max:86400})}${input('protection.mbuFraction','ECC: 동시 다중비트 비율 (%)',{value:p.mbuFraction*100,percent:true,min:0,max:100,help:'같은 워드 내 2-bit 사건 가정'})}${input('protection.commonFraction','TMR: 공통원인 비율 (%)',{value:p.commonFraction*100,percent:true,min:0,max:100})}${input('protection.functionalFraction','잔존 오류의 기능 영향 (%)',{value:p.functionalFraction*100,percent:true,min:0,max:100})}${input('protection.coverage','기능 오류 검출·복구 성공 (%)',{value:p.coverage*100,percent:true,min:0,max:100})}</div><p class="input-note">보호효과·기능 영향·성공률은 사용자가 검증해야 하는 설계 가정입니다.</p></div>`)}${card('보호 후 잔존 사건 비교',`<div class="card-body"><p class="text-muted small">논리 장비 1대 · 사건/일 · 선형 축</p>${r.soft?bars:'<div class="empty"><strong>원시 비트 오류율이 필요합니다</strong>부품·궤도에 맞는 raw SEU 자료를 입력하세요.</div>'}${kv('선택 설계 원시 비트 오류',`${fmt(r.soft?.physicalRawPerDay)} 회/일`)}${kv('보호 후 잔존 사건',`${fmt(r.soft?.uncorrectablePerDay)} 회/일`)}${kv('모델상 복구 중단시간',`${fmt(r.downtime,5)} 초/일`)}${kv('미복구 기능 사건',`${fmt(r.unhandled)} 회/일`)}${kv('장비 소비전력',`${fmt(r.cost.powerW)} W`)}<p class="input-note">복구 중단시간은 검출·복구 가능한 SEU와 입력된 SEFI만 반영합니다. SEL·영구고장·부품 수명·위성망 가용도는 포함하지 않습니다.</p></div>`)}</div><div class="spaced">${card('계산에 적용한 가정',`<div class="card-body explain"><p><strong>ECC:</strong> 독립 오류가 동일 워드·주기 안에 2회 이상 쌓이는 확률과, 같은 워드의 동시 2-bit 사건을 합산합니다. 주기마다 워드가 정상화된다고 가정합니다. 오류 위치의 실제 상관관계·인터리빙 효과는 시험자료로 보완해야 합니다.</p><p><strong>TMR:</strong> 3개 복제본 중 2개 이상에 오류가 생기는 경우를 계산하고 공통원인 사건을 더합니다. 투표기는 이상적이며, 주기마다 재동기화된다고 가정합니다. 소자 수·전력·반도체 구매비는 3배 구성을 반영합니다.</p><p><strong>기능 복구:</strong> 비트 오류, 잔존 사건, 기능 중단을 구분합니다. 정상화 실패와 파괴성 고장은 중단시간 그래프에 숨겨 합산하지 않습니다.</p></div>`)}</div>`;
}
const EVENT_TYPES={seu:'SEU',sel:'SEL',sefi:'SEFI'};
function verificationPage(r){
 const tasks=verificationTasks(r,project),done=tasks.filter(t=>t.status==='완료').length;
 const bounds=Object.fromEntries(Object.keys(EVENT_TYPES).map(k=>[k,project.flight.events[k]===0?zeroEventUpperRate(project.flight.months,project.flight.devices):null]));
 const zeroTypes=Object.keys(EVENT_TYPES).filter(k=>project.flight.events[k]===0);
 const envIndex=buildEnvironmentIndex(project);
 const flightDose=evaluate(project,project.selectedPartId,'sso500',envIndex).dose?.annualTidKrad;
 const flightTotal=flightDose===undefined||flightDose===null?null:flightDose*project.flight.months/12;
 const rows=ORBITS.slice(1).map(o=>{const ev=evaluate(project,project.selectedPartId,o.id,envIndex);return `<tr><td>${h(o.label)}</td><td class="number">${fmt(flightTotal)}</td><td class="number">${fmt(ev.missionDose)}</td><td>${badge('추가 환경·효과 검증','amber')}</td></tr>`;});
 const eventRows=Object.entries(EVENT_TYPES).map(([k,label])=>`<tr><td>${label}</td><td class="number">${fmt(project.flight.events[k],0)}</td><td class="number">${bounds[k]===null?'—':fmt(bounds[k])}</td></tr>`);
 return `<div class="metrics">${metric('검증 작업',tasks.length,'항목','환경·TID·SEE·복구·추적성')}${metric('진행상태 완료',done,'항목','완료 표시는 담당자 기록이며 승인 아님')}${metric('관측 소자·기간',`${project.flight.devices} × ${project.flight.months}`,'개·월','Space-MaCS 비교 시나리오')}${metric('미관측 사건유형',`${zeroTypes.length} / 3`,'유형',zeroTypes.length?zeroTypes.map(k=>EVENT_TYPES[k]).join('·')+' 0건 관측':'전 유형 사건 관측됨')}</div>${card('시제기·양산 적용 검증계획',`<div class="tasks">${tasks.map(t=>`<div class="task">${badge(t.category,t.priority==='높음'?'amber':'')}<div><h3>${h(t.title)}</h3><p>${h(t.detail)}</p></div><label><span class="sr-only">${h(t.title)} 진행상태</span><select data-task="${t.id}">${['계획','진행','완료'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`).join('')}</div>`,btn('계획 CSV','tasks','download'))}<div class="grid-equal">${card('Space-MaCS 관측조건',`<div class="card-body"><div class="field-grid">${input('flight.months','관측기간 (개월)',{min:.01,max:120})}${input('flight.devices','관측 소자 수',{min:1,step:1})}${input('flight.events.seu','SEU 관측 사건 수',{min:0,step:1})}${input('flight.events.sel','SEL 관측 사건 수',{min:0,step:1})}${input('flight.events.sefi','SEFI 관측 사건 수',{min:0,step:1})}</div>${table(['사건유형','관측 사건','0건 시 95% 상한<br>회/소자·일'],eventRows)}<p class="input-note">사건유형별로 분리해 기록합니다. 완전 검출·일정 사건율의 포아송 모형을 가정합니다. 사건이 1건 이상인 유형은 0건 상한을 표시하지 않습니다.</p><div class="spaced">${notice('0건 관측은 고장률 0 또는 면역성을 의미하지 않습니다. 산출한 상한은 같은 관측환경의 값이며, 목표궤도에 직접 전용할 수 없습니다.','info')}</div></div>`)}${card('목표 임무와 검증 범위 비교',table(['목표 궤도','500 km 검증 선량<br>krad(Si)','목표 임무 선량<br>krad(Si)','검토'],rows,'500 km SSO의 경사각은 97.4° 가정입니다. 동일 선량만으로 입자 에너지·SEE·열조건의 동등성이 성립하지 않습니다.'))}</div>`;
}
