function envEditor(r){const rate=r.rate,dose=r.dose;
 const approximated=r.doseInterpolated||r.doseNearestOnly;
 // An interpolated/nearest-thickness dose describes a neighboring data point, not this exact
 // shield thickness: never prefill its source/model/epoch as if they were this point's own
 // provenance, or a plain "적용" click would silently mislabel an estimate as sourced data.
 const doseSource=approximated?'':dose?.source||'',doseModel=approximated?'':dose?.model||'',doseEpoch=approximated?'':dose?.epoch||'';
 const approxNotice=r.doseInterpolated?notice(`<strong>차폐두께 보간값 표시 중</strong> ${project.mission.shieldMm} mm의 실측 자료가 없어 ${r.doseBracket[0]}–${r.doseBracket[1]} mm 자료 사이의 로그선형 보간값을 표시합니다. 실측값으로 저장하려면 출처를 새로 입력하세요.`,'info'):r.doseNearestOnly?notice(`<strong>범위 밖 최근접값 표시 중</strong> ${project.mission.shieldMm} mm가 보유 차폐 자료 범위를 벗어나 가장 가까운 두께의 선량을 그대로 표시합니다 (외삽 아님). 실측값으로 저장하려면 출처를 새로 입력하세요.`,'info'):'';
 return `${approxNotice}<form id="env-editor"><div class="field-grid"><label><span>연간 TID (krad(Si)/년)</span><input name="dose" type="number" min="0" step="any" value="${h(dose?.annualTidKrad??'')}" placeholder="자료 없으면 비움"></label><label><span>원시 SEU (회/bit/일)</span><input name="seu" type="number" min="0" step="any" value="${h(rate?.seuPerBitDay??'')}" placeholder="자료 없으면 비움"></label><label><span>SEFI (회/소자/일)</span><input name="sefi" type="number" min="0" step="any" value="${h(rate?.sefiPerDeviceDay??'')}"></label><label><span>SEL (회/소자/일)</span><input name="sel" type="number" min="0" step="any" value="${h(rate?.selPerDeviceDay??'')}"></label><label><span>근거 유형</span><select name="basis"><option value="synthetic" ${dose?.basis==='synthetic'?'selected':''}>예시·가정</option><option value="user" ${dose?.basis==='user'?'selected':''}>사용자 해석자료</option><option value="test" ${dose?.basis==='test'?'selected':''}>시험자료와 연결된 해석</option></select></label><label><span>오류율 기준</span><select name="rateKind"><option value="raw" ${rate?.rateKind!=='effective'?'selected':''}>원시 비트 오류율 (raw)</option><option value="effective" ${rate?.rateKind==='effective'?'selected':''}>보호 후 출력율 (effective)</option></select></label><label class="full"><span>자료 제목·파일명·URL</span><input name="source" required value="${h(doseSource)}"></label><label><span>환경 모델·차폐 형상</span><input name="model" required value="${h(doseModel)}"></label><label><span>분석기간·태양활동 조건</span><input name="epoch" required value="${h(doseEpoch)}"></label></div><div class="spaced"><button class="btn primary" type="submit">선택 조건에 적용</button></div><p class="input-note">${h(ORBITS.find(o=>o.id===project.mission.orbitId).label)} · ${project.mission.shieldMm} mm · ${h(r.part.name)}에 적용합니다. 선량은 같은 환경의 모든 부품에 공유됩니다. 두 차폐두께 자료 사이는 로그선형 보간하며, 범위 밖은 외삽하지 않습니다. 고도·경사각은 여전히 정확히 일치해야 합니다.</p></form>`;}
function dataPage(r){return `<div class="grid-equal" style="margin-top:0">${card('선택 조건의 환경·오류율 입력',`<div class="card-body">${partPicker()}${envEditor(r)}</div>`)}<div class="stack">${card('분석자료 가져오기·저장',`<div class="card-body"><p class="explain">시나리오 JSON에는 임무·부품·환경·보호설계·비용·검증 상태와 설계 실험의 비트 상태·난수 시드가 저장됩니다. 반복 실험 결과는 같은 설정으로 다시 실행해 재현합니다. 가져온 자료는 이 브라우저에서 계산하며 서버로 업로드하지 않습니다.</p><div class="download-box"><p><strong>환경·오류율 CSV</strong><br>SPENVIS 원본 전체를 직접 읽는 형식이 아닙니다. 외부 해석 결과를 정규화 양식의 단위에 맞춰 정리하세요.</p><div class="button-row">${btn('빈 양식','template','download')}${btn('현재 환경 CSV','environment','download')}${btn('CSV 가져오기','import-env','upload','primary')}</div></div><p class="small text-muted">CSV 가져오기는 전체 환경자료를 교체합니다. 변경 전 시나리오 JSON을 저장할 수 있습니다. 빈 수치는 ‘미확보’, 0은 실제 0으로 처리합니다.</p><div class="button-row spaced">${btn('JSON 저장','save','download')}${btn('JSON 불러오기','load','upload')}${btn('예시 시나리오 복원','reset')}</div></div>`)}${card('자료 현황',`<div class="card-body">${kv('부품 자료',`${project.parts.length}개`)}${kv('환경·부품 조건',`${project.environments.length}행`)}${kv('현재 시나리오',h(project.title))}<div class="spaced">${input('title','시나리오 이름',{type:'text'})}</div></div>`)}</div></div><div class="grid-equal">${card('계산방법과 적용 범위',`<div class="card-body"><details class="method" open><summary>선량과 TID 여유</summary><div class="explain"><p>일치하는 고도·경사각·차폐의 연간 평균 선량만 사용합니다. 임무 선량 = 연간 선량 × 수명, 요구선량 = 임무 선량 × 설계 여유계수입니다. TID 수치 여유 = 부품 TID 근거값 / 요구선량입니다.</p><p>방사선 수송·태양활동 시계열을 자체 계산하지 않습니다. 차폐를 두껍게 했을 때의 효과는 해당 조건의 외부 자료가 있어야 비교합니다. 초기 합성 수치에는 물리적 예측 의미가 없습니다.</p></div></details><details class="method"><summary>메모리 오류·보호 모델</summary><div class="explain"><p>외부 계산된 per-bit-day 원시 SEU율에 소자 용량과 장비당 소자 수를 곱합니다. 양성자/중이온 단면적의 스펙트럼 적분은 SPENVIS 등 외부 도구에서 수행한 결과를 사용합니다.</p><p>ECC는 포아송 동일 워드 다중오류 확률과 동시 2-bit 사건을 합산합니다. TMR은 독립 복제본의 다수결 실패와 공통원인 항을 사용합니다. 모든 보호 워드가 점검주기마다 정상화된다고 가정합니다.</p><p>재시작 중단시간은 검출·복구 성공 사건의 포아송 점유모형입니다. 기능 영향 비율·복구 성공률은 사용자가 검증해야 합니다. SEE 전체의 신뢰도나 위성 고장확률을 계산하지 않습니다.</p></div></details><details class="method"><summary>0건 관측·95% 사건율 상한</summary><div class="explain"><p>0건 관측의 단측 95% 상한 = −ln(0.05) / (관측 소자 수 × 관측일수). 일정 사건율, 소자 간 독립성과 완전 검출을 가정합니다. 같은 관측환경에만 적용되며 다른 궤도에 직접 전용하지 않습니다.</p></div></details><details class="method"><summary>설계 실험과 예비평가의 범위</summary><div class="explain"><p>64비트 SECDED·TMR 설계 실험과 메모리 적용성 예비평가 도구입니다. 트랜지스터 TCAD, 열해석, DDD 수명모델, FPGA 전체 상태 해석, 임무 인증, 위성망 운용 가용도는 포함하지 않습니다. DDD·SEB·SEGR 등은 검증 공백으로 별도 평가해야 합니다.</p><p>시나리오 저장본에는 모든 입력자료가 포함됩니다. 이 페이지를 새로고침하면 저장하지 않은 입력은 예시 시나리오로 초기화됩니다.</p></div></details></div>`)}${card('방법론·제품 사양 출처',`<div class="card-body"><ul class="source-list">${SOURCES.map(s=>`<li><a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.name)} ↗</a><p>${h(s.note)}</p></li>`).join('')}</ul><p class="input-note">제품 자료 확인 기준: 2026-09-06. 조건·등급·개정판과 구매 로트는 적용 전에 재확인하세요.</p></div>`)}</div>`;}

function labCsv(){
 if(!campaign)throw Error('반복 실험을 먼저 실행하세요.');
 const c=campaign;
 const rows=[['model','data_hex','architecture','pattern','trials','seed','correct','detected_stop_required','silent_corruption','correct_fraction','scope'],...Object.entries(c.counts).map(([k,n])=>[c.model,c.hex,ARCHITECTURES[k],PATTERNS[c.pattern],c.trials,c.seed,n.correct,n.detected,n.silent,n.correct/c.trials,c.scope])];
 download('kleo-chip-fault-campaign.csv',toCsv(rows),'text/csv;charset=utf-8');notify('패턴·시드·범위를 포함한 실험 결과를 저장했습니다.');
}
function printLabReport(){
 const lab=project.lab,outcomes=inspectLab(lab),labels={correct:'정상 데이터 확보',detected:'검출·출력 사용 중단',silent:'미검출 손상'};
 document.querySelector('#print-root').innerHTML=`<h1>K-LEO 반도체 보호설계 실험</h1><p>${h(project.title)} · V1.1.0 · ${h(new Date().toLocaleString('ko-KR'))}</p><p>64비트 기준 데이터: ${h(lab.hex)}. 수동 오류 주입 상태는 시나리오 JSON으로 재현할 수 있습니다.</p>${table(['구조','저장 bit','회로 계산 데이터','판정','오류 bit'],Object.entries(outcomes).map(([k,v])=>`<tr><td>${h(ARCHITECTURES[k])}</td><td>${v.physicalBits}</td><td>${v.hex}</td><td>${labels[v.status]}</td><td>${v.mismatch}</td></tr>`))}<h2>반복 오류 주입</h2>${campaign?`<p>패턴 ${h(PATTERNS[campaign.pattern])} · ${campaign.trials}회 · 시드 ${campaign.seed} · 기준값 ${campaign.hex}</p>${table(['구조','정상 데이터','검출·중단 필요','미검출 손상'],Object.entries(campaign.counts).map(([k,n])=>`<tr><td>${h(ARCHITECTURES[k])}</td><td>${n.correct}</td><td>${n.detected}</td><td>${n.silent}</td></tr>`))}`:'<p>실행한 반복 실험이 없습니다.</p>'}<h2>해석 범위</h2><p>확장 해밍 SECDED (72,64), 비트별 TMR 다수결과 불일치 검출을 계산합니다. TMR 투표기·불일치 검출기는 이상적입니다. 스크러빙은 회로가 계산한 값만 다시 씁니다. 원본 기준값을 이용한 복구는 하지 않습니다.</p><p>반복 실험은 매 시행 초기화 후 구조별 같은 개수의 서로 다른 물리 비트를 반전합니다. 상관 패턴은 TMR의 두 복제본 동일 비트, 다른 구조는 서로 다른 두 물리 비트입니다. 시간·궤도 방사선 발생률·물리 레이아웃·위성 신뢰도는 계산하지 않습니다. 결과 비율을 궤도 발생률에 직접 곱하지 마세요.</p><p>참고: NASA FPGA Mitigation Strategies for Critical Space Applications (2018), https://ntrs.nasa.gov/citations/20180006778</p>`;
 window.print();
}
function notify(msg,error=false){const t=document.querySelector('#toast');clearTimeout(toastTimer);t.textContent=msg;t.hidden=false;t.className=error?'error':'';toastTimer=setTimeout(()=>t.hidden=true,5500);}
function update(fn){const draft=structuredClone(project);fn(draft);validateProject(draft);project=draft;render();}
function download(name,body,type){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const saveProject=()=>{download('kleo-chip-scenario.json',JSON.stringify(project,null,2),'application/json');notify('시나리오 JSON을 저장했습니다. 다시 불러와 이어서 분석할 수 있습니다.');};
function resultCsv(){const rows=[['scenario','part_id','part_name','orbit','shield_mm','years','mission_tid_krad_si','required_tid_krad_si','tid_margin_ratio','logical_raw_bit_upsets_day','residual_events_day','modeled_recovery_downtime_sec_day','unrecovered_functional_events_day','protection','cost_krw','environment_basis','dose_method','part_tid_basis','environment_source','part_tid_source','unresolved','scope']];const envIndex=buildEnvironmentIndex(project);for(const p of project.parts)for(const o of ORBITS){const r=evaluate(project,p.id,o.id,envIndex);const doseMethod=r.doseInterpolated?'interpolated':r.doseNearestOnly?'nearest_out_of_range':r.dose?'exact':'missing';rows.push([project.title,p.id,p.name,o.label,project.mission.shieldMm,project.mission.years,r.missionDose,r.requiredDose,r.tidRatio,r.soft?.rawPerDay,r.soft?.uncorrectablePerDay,r.downtime,r.unhandled,modeLabel[project.protection.mode],r.cost.total,r.dose?.basis,doseMethod,p.tidBasis,r.dose?.source,p.tidSource,r.reasons.join(' / '),'예비평가; 합성자료는 실제 예측 아님; 중단시간은 검출·복구 가능한 SEU/입력된 SEFI만']);}download('kleo-chip-results.csv',toCsv(rows),'text/csv;charset=utf-8');notify('입력 근거와 자료 공백을 포함한 결과 CSV를 저장했습니다.');}
function printReport(){const r=evaluate(project),o=ORBITS.find(x=>x.id===project.mission.orbitId);document.querySelector('#print-root').innerHTML=`<h1>K-LEO 우주반도체 적용성 검토</h1><p class="print-meta">${h(project.title)} · ${h(new Date().toLocaleString('ko-KR'))}</p>${evidenceNotice(r)}<p>평가 부품: <strong>${h(r.part.name)}</strong> · ${h(o.label)} · 수명 ${project.mission.years}년 · Al 등가 차폐 ${project.mission.shieldMm}mm · 선량 여유계수 ${project.mission.doseMargin}</p><h2>궤도별 수치 비교</h2>${table(['궤도','누적선량<br>krad(Si)','요구선량<br>krad(Si)','TID 여유','원시 오류<br>회/일','환경 근거'],orbitRows())}<h2>보호·비용 가정</h2><p>보호설계 ${h(modeLabel[project.protection.mode])}, 점검주기 ${project.protection.scrubSec}초, 복구시간 ${project.protection.recoverySec}초, 검출·복구 성공 ${fmt(project.protection.coverage*100)}%, 기능 영향 ${fmt(project.protection.functionalFraction*100)}%.</p><p>모델상 복구 중단 ${fmt(r.downtime,5)}초/일 · 미복구 기능 사건 ${fmt(r.unhandled)}회/일. 영구고장·SEL·위성망 가용도 제외.</p><p>제작·검증비 ${won(r.cost.total)}${r.cost.total===null?'':'원'} · 예비품 포함 ${r.cost.boards}대. 금액은 입력 가정이며 발사·운용·교체비 제외.</p><h2>검증계획</h2><ul>${verificationTasks(r,project).map(t=>`<li><strong>[${h(t.status)}] ${h(t.title)}</strong><br>${h(t.detail)}</li>`).join('')}</ul><h2>근거·제한사항</h2><p>환경: ${h(r.dose?.source||'자료 부족')}<br>모델·시기: ${h(r.dose?.model||'자료 부족')} / ${h(r.dose?.epoch||'자료 부족')}<br>부품 TID: ${h(r.part.tidSource)} (${h(BASIS_LABELS[r.part.tidBasis])})<br>시험조건: ${h(r.part.notes)}</p><p>추가 확인: ${h(r.reasons.join(' / '))}</p><p>보유한 두 차폐두께 자료 사이에서만 로그선형 보간하며, 그 범위를 벗어나거나 고도·경사각이 다르면 보간·외삽하지 않습니다. TID 수치 여유 충족은 부품 채택 승인이 아니며, 비트 오류율은 위성 고장확률이 아닙니다.</p>`;window.print();}

app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.labView){update(p=>p.lab.view=b.dataset.labView);app.querySelector(`[data-lab-view="${b.dataset.labView}"]`)?.focus({preventScroll:true});return;}
 if(b.dataset.labBit!==undefined){update(p=>p.lab=flipBit(p.lab,b.dataset.bank,Number(b.dataset.labBit),Number(b.dataset.copy)));app.querySelector(`[data-lab-bit="${b.dataset.labBit}"][data-bank="${b.dataset.bank}"][data-copy="${b.dataset.copy}"]`)?.focus({preventScroll:true});return;}
 if(b.dataset.page){page=b.dataset.page;render();window.scrollTo({top:0});return;}
 if(b.dataset.orbit){update(p=>p.mission.orbitId=b.dataset.orbit);return;}
 if(b.dataset.part){update(p=>p.selectedPartId=b.dataset.part);return;}
 if(b.dataset.mode){update(p=>p.protection.mode=b.dataset.mode);return;}
 const a=b.dataset.action;if(!a)return;
 if(a.startsWith('go-')){page=a.slice(3);render();window.scrollTo({top:0});return;}
 if(['lab-single','lab-double','lab-common','lab-triple'].includes(a)){update(p=>p.lab=injectPreset(p.lab,a.slice(4)));return;}
 if(a==='lab-clear'){update(p=>p.lab=resetMemory(p.lab));return;}
 if(a==='lab-scrub'){
  const before=inspectLab(project.lab)[project.lab.view];
  update(p=>p.lab=scrubMemory(p.lab));
  notify(project.lab.view==='ecc'&&before.flag==='uncorrectable'?'정정 불가 신호: 저장값을 덮어쓰지 않았습니다.':inspectLab(project.lab)[project.lab.view].mismatch?'회로 계산값을 썼지만 원본과 다른 데이터가 남아 있습니다.':'회로가 계산한 정상값으로 저장 비트를 복구했습니다.');return;
 }
 if(a==='lab-run'){campaign=runCampaign(project.lab);render();notify('반복 오류 주입 실험을 완료했습니다.');return;}
 if(a==='lab-csv'){labCsv();return;}
 if(a==='save')saveProject();
 if(a==='load')document.querySelector('#project-file').click();
 if(a==='results')resultCsv();
 if(a==='environment')download('kleo-chip-environment.csv',environmentCsv(project),'text/csv;charset=utf-8');
 if(a==='import-env')document.querySelector('#environment-file').click();
 if(a==='template'){const rows=[CSV_COLUMNS,...ORBITS.map(o=>[o.id,o.altitudeKm,o.inclinationDeg,project.mission.shieldMm,'',project.selectedPartId,'','','','user','분석자료 제목 또는 URL','환경 모델과 차폐 형상','분석 시기와 태양활동','raw'])];download('kleo-chip-environment-template.csv',toCsv(rows),'text/csv;charset=utf-8');}
 if(a==='tasks'){const rows=[['category','task','priority','status','details','part','orbit'],...verificationTasks(evaluate(project),project).map(t=>[t.category,t.title,t.priority,t.status,t.detail,selected().name,project.mission.orbitId])];download('kleo-chip-verification.csv',toCsv(rows),'text/csv;charset=utf-8');}
 if(a==='print'){if(page==='lab')printLabReport();else printReport();}
 if(a==='reset'){if(window.confirm('현재 입력을 예시 시나리오로 되돌릴까요? 저장하지 않은 변경은 없어집니다.')){project=createProject();campaign=null;render();notify('예시 시나리오로 복원했습니다.');}}
 if(a==='add-part'||a==='clone-part'){update(p=>{const original=structuredClone(p.parts.find(x=>x.id===p.selectedPartId));const id='user-'+crypto.randomUUID().slice(0,8);const part=a==='clone-part'?{...original,id,name:original.name+' · 복사',tidBasis:'user'}:{...original,id,name:'사용자 메모리',vendor:'사용자 입력',grade:'미분류',tidKrad:null,tidBasis:'user',tidSource:'미확보',source:'사용자 입력',notes:'시험조건·근거자료를 입력하세요.',lot:'미확인',unitCostKrw:null,powerW:null};p.parts.push(part);p.selectedPartId=id;});notify('부품을 추가했습니다. 환경·오류율 자료는 별도로 연결하세요.');}
 }catch(error){notify(error.message,true);}});

app.addEventListener('change',e=>{const el=e.target;try{
 if(el.dataset.labConfig){const key=el.dataset.labConfig;if(!['pattern','trials','seed'].includes(key))return;const value=key==='pattern'?el.value:el.value.trim()===''?NaN:Number(el.value);const next=structuredClone(project.lab);next[key]=value;validateLab(next);campaign=null;update(p=>p.lab=next);return;}
 if(el.dataset.task){update(p=>p.taskStatus[el.dataset.task]=el.value);return;}
 if(el.dataset.partBasis){update(p=>p.parts.find(x=>x.id===p.selectedPartId).tidBasis=el.value);return;}
 if(!el.dataset.path)return;const path=el.dataset.path;
 let value=el.type==='number'?(el.value===''&&el.dataset.nullable?null:Number(el.value)):el.value;
 if(el.type==='number'&&el.value===''&&!el.dataset.nullable)throw Error('숫자 입력이 필요합니다.');
 if(el.dataset.percent)value/=100;
 update(p=>{const seg=path.split('.');let obj=p;if(seg[0]==='part'){obj=p.parts.find(x=>x.id===p.selectedPartId);seg.shift();}for(const k of seg.slice(0,-1))obj=obj[k];obj[seg.at(-1)]=value;if(path.startsWith('part.')&&['tidKrad','densityBits','tidSource'].includes(seg.at(-1)))obj.tidBasis='user';});
 }catch(error){el.setAttribute('aria-invalid','true');notify(error.message,true);}});

app.addEventListener('submit',e=>{if(e.target.id==='lab-data-form'){e.preventDefault();try{const hex=new FormData(e.target).get('hex').trim();const next=resetMemory(project.lab,hex);campaign=null;update(p=>p.lab=next);notify('기준 데이터를 기록하고 메모리를 초기화했습니다.');}catch(error){notify(error.message,true);}return;}if(e.target.id!=='env-editor')return;e.preventDefault();try{
 const f=new FormData(e.target),num=k=>f.get(k).trim()===''?null:Number(f.get(k));
 update(p=>{const m=p.mission,o=ORBITS.find(x=>x.id===m.orbitId),basis=f.get('basis'),dose=num('dose');const matched=x=>x.orbitId===m.orbitId&&Math.abs(x.shieldMm-m.shieldMm)<1e-8;
 for(const row of p.environments.filter(matched)){const changed=row.annualTidKrad!==dose||row.basis!==basis||row.source!==f.get('source')||row.model!==f.get('model')||row.epoch!==f.get('epoch');if(changed&&row.partId!==p.selectedPartId){row.seuPerBitDay=null;row.sefiPerDeviceDay=null;row.selPerDeviceDay=null;row.notes='환경 조건 또는 근거 변경: 이 부품의 오류율 재해석 필요';}row.annualTidKrad=dose;row.basis=basis;row.source=f.get('source');row.model=f.get('model');row.epoch=f.get('epoch');}
 const row={orbitId:o.id,altitudeKm:o.altitudeKm,inclinationDeg:o.inclinationDeg,shieldMm:m.shieldMm,annualTidKrad:dose,partId:p.selectedPartId,seuPerBitDay:num('seu'),sefiPerDeviceDay:num('sefi'),selPerDeviceDay:num('sel'),basis,source:f.get('source'),model:f.get('model'),epoch:f.get('epoch'),rateKind:f.get('rateKind'),notes:'선택 조건에서 직접 입력한 자료'};
 const i=p.environments.findIndex(x=>matched(x)&&x.partId===p.selectedPartId);if(i<0)p.environments.push(row);else p.environments[i]=row;});notify('선택 조건의 환경·오류율을 적용했습니다.');
 }catch(error){notify(error.message,true);}});

document.querySelector('#project-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4e6)throw Error('프로젝트는 4 MB 이하만 지원합니다.');const p=JSON.parse(await file.text());validateProject(p);p.lab??=createLab();project=p;campaign=null;render();notify('시나리오와 모든 입력자료를 불러왔습니다.');}catch(error){notify('불러오기 실패: '+error.message,true);}finally{e.target.value='';}});
document.querySelector('#environment-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('CSV는 2 MB 이하만 지원합니다.');const next=importEnvironmentCsv(project,await file.text());if(window.confirm(`검증된 ${next.environments.length}행으로 전체 환경자료를 교체할까요?`)){project=next;render();notify('환경자료를 교체했습니다. 일치하는 조건만 계산에 사용합니다.');}}catch(error){notify('CSV 가져오기 실패: '+error.message,true);}finally{e.target.value='';}});
try{render();}catch(e){app.innerHTML=`<main class="boot"><h1>분석 화면을 열 수 없습니다</h1><p>${h(e.message)}</p><p>페이지를 새로고침해 다시 시도해주세요.</p></main>`;}
